select scope_key, count(*) stages, count(*) filter (where status='complete') done, string_agg(operation_key||'='||status||coalesce('('||last_error||')',''), ', ' order by created_at) filter (where status<>'complete') not_done, to_char(max(updated_at),'HH24:MI') last_upd from projection_pipeline_state where pipeline_key='rolling_forge_pipeline' and scope_key like 'daily_incremental:%' and created_at > now() - interval '31 days' group by 1 order by 1
